        if (seconds > 0) {
            seconds--;
        } else {
            seconds = 59;
            if (minutes > 0) {
                minutes--;
            } else {
                minutes = 59;
                if (hours > 0) {
                    hours--;
                } else {
                    hours = 23;
                    if (days > 0) {
                        days--;
                    }
                }
            }
        }

        if (countdownNumbers.length >= 2) {
            countdownNumbers[0].textContent = days.toString().padStart(2, '0');
            countdownNumbers[1].textContent = hours.toString().padStart(2, '0');
        }

        // Update aria-label for accessibility
        const countdownContainer = document.querySelector('.countdown');
        if (countdownContainer) {
            countdownContainer.setAttribute('aria-label', `Sale ends in ${days} days, ${hours} hours`);
        }
    }

    setInterval(updateCountdown, 1000);

    // 4. Newsletter Form Handling
    const newsletterForm = document.querySelector('.newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;

            // Create a status message for screen readers
            const statusMessage = document.createElement('div');
            statusMessage.setAttribute('role', 'status');
            statusMessage.setAttribute('aria-live', 'polite');
            statusMessage.classList.add('sr-only');
            document.body.appendChild(statusMessage);

            // Simulate success
            const originalButton = newsletterForm.querySelector('button');
            const originalText = originalButton.textContent;

            originalButton.textContent = 'Subscribed!';
            originalButton.disabled = true;
            statusMessage.textContent = `Thank you for subscribing with ${email}`;

            setTimeout(() => {
                newsletterForm.reset();
                originalButton.textContent = originalText;
